private async gatherBugs(parentIds: number[]) {
  const allBugs: EnrichedBug[] = [];
  const storyTitles = new Map<number, string>();

  for (const storyId of parentIds) {
    // Fetch WITH relations — a plain getWorkItem omits the link graph we need
    const wi = await this.client.getWorkItemWithRelations(storyId);
    // Blank titles happen on partially-created items; keep a usable caption
    const storyTitle = wi.fields?.['System.Title'] || `Story #${storyId}`;
    storyTitles.set(storyId, storyTitle);

    // Hierarchy-Forward = OUTBOUND links = children (Reverse would be the parent)
    const childIds = this.client.extractRelationIds(wi.relations || [], 'System.LinkTypes.Hierarchy-Forward');
    if (childIds.length === 0) continue; // no children — skip the batch round-trip

    // One batched call per story, projecting ONLY the fields the report reads
    const children = await this.client.getWorkItemsBatch(childIds, [
      'System.Id', 'System.Title', 'System.WorkItemType', 'System.State',
      'Microsoft.VSTS.Common.Severity', 'Microsoft.VSTS.Common.Priority',
      'System.AssignedTo', 'System.CreatedDate', 'Microsoft.VSTS.Common.ResolvedDate',
    ]);

    for (const child of children) {
      // Children include Tasks/Test-Cases too — keep only Bugs
      if (child.fields?.['System.WorkItemType'] === 'Bug') {
        allBugs.push(this.enrichBug(child, storyId, storyTitle));
      }
    }
  }
  return { bugs: allBugs, storyTitles };
}

private enrichBug(raw: any, parentStoryId: number, parentStoryTitle: string): EnrichedBug {
  const f = raw.fields || {};
  const createdDate = f['System.CreatedDate'] || '';
  const resolvedDate = f['Microsoft.VSTS.Common.ResolvedDate'] || null; // null while still open

  let daysToFix: number | null = null; // stays null for unresolved bugs — NOT 0
  if (resolvedDate && createdDate) {   // need both endpoints to compute a span
    const diff = new Date(resolvedDate).getTime() - new Date(createdDate).getTime();
    // ms -> days, rounded to 0.1; clamp >= 0 because ADO dates can go backwards after edits
    daysToFix = Math.max(0, Math.round(diff / (1000 * 60 * 60 * 24) * 10) / 10);
  }

  return {
    id: raw.id ?? f['System.Id'] ?? 0, // id lives at top level OR in fields depending on the API
    title: f['System.Title'] || '',
    state: f['System.State'] || 'Unknown',
    severity: f['Microsoft.VSTS.Common.Severity'] || 'Unspecified',
    assignedTo: this.client.extractDisplayName(f['System.AssignedTo']), // identity object -> plain name
    createdDate, resolvedDate, daysToFix,
    parentStoryId, parentStoryTitle,
    // ... plus description, repro steps and tags
  } as EnrichedBug;
}

private buildReport(bugs: EnrichedBug[], storyTitles: Map<number, string>, input: BugIntelInput) {
  const FIXED_STATES = ['Resolved', 'Closed'];
  const OPEN_STATES = ['New', 'Active']; // note: not exhaustive — custom states count as neither
  const assigneeMap = new Map<string, { total: number; open: number; fixed: number }>();

  for (const bug of bugs) {
    const aName = bug.assignedTo || 'Unassigned'; // keep null-assignee bugs in the tally
    if (!assigneeMap.has(aName)) assigneeMap.set(aName, { total: 0, open: 0, fixed: 0 });
    const a = assigneeMap.get(aName)!;
    a.total++;
    if (FIXED_STATES.includes(bug.state)) a.fixed++;
    if (OPEN_STATES.includes(bug.state)) a.open++;
  }

  const fixedBugs = bugs.filter(b => FIXED_STATES.includes(b.state)).length;
  const fixRate = bugs.length > 0 ? fixedBugs / bugs.length : 0; // guard empty feature

  // Only resolved bugs have a daysToFix — exclude nulls so open bugs don't skew the mean to 0
  const daysArr = bugs.filter(b => b.daysToFix !== null).map(b => b.daysToFix!);
  const avgDaysToFix = daysArr.length > 0
    ? Math.round((daysArr.reduce((a, b) => a + b, 0) / daysArr.length) * 10) / 10 // 0.1-day precision
    : null; // no resolved bugs yet -> null, not 0

  // ... plus counts by severity, priority, and per-story breakdowns
}

private generateInsights(summary, perStory, perAssignee): string[] {
  const insights: string[] = [];

  // Hotspot story — perStory is pre-sorted desc by bug count, so [0] is the worst offender
  const hotspot = perStory[0];
  if (hotspot && hotspot.bugCount > 0) { // suppress on a clean feature
    insights.push(
      `Story #${hotspot.storyId} (${hotspot.storyTitle}) is a hotspot with ${hotspot.bugCount} bugs (${hotspot.openCount} still open)`,
    );
  }

  // Fix rate commentary — require >=3 bugs so a lone unfixed bug (0%) isn't flagged as systemic
  const pct = Math.round(summary.fixRate * 100);
  if (summary.fixRate < 0.5 && summary.totalBugs >= 3) {
    insights.push(`Bug resolution is behind — only ${pct}% resolved. Consider allocating more dev time`);
  }

  // Assignee with the most open bugs — first with open work = most-loaded (list is pre-sorted)
  const topAssignee = perAssignee.find(a => a.openBugs > 0);
  if (topAssignee && topAssignee.openBugs >= 3) { // only a real pile-up trips the warning
    insights.push(`${topAssignee.name} has ${topAssignee.openBugs} open bugs — check if support is needed`);
  }

  return insights; // may be empty — nothing crossed a threshold
}

private generateRecommendations(summary, perStory): string[] {
  const recs: string[] = [];

  // || 0 so a missing severity bucket reads as 0, not NaN, in the sum
  const critHigh = (summary.bySeverity['1 - Critical'] || 0) + (summary.bySeverity['2 - High'] || 0);
  if (critHigh > 0) {
    recs.push(`Prioritize fixing ${critHigh} Critical/High severity bugs before sprint end`);
  }

  // Zero bugs is treated as SUSPICIOUS (untested), not clean — the inverse of a hotspot
  const zeroBugStories = perStory.filter(s => s.bugCount === 0);
  if (zeroBugStories.length > 0) {
    const ids = zeroBugStories.map(s => `#${s.storyId}`).join(', ');
    recs.push(`Stories ${ids} have no bugs — verify test execution has started`);
  }

  // Feature-wide backlog threshold — higher than the per-assignee >=3 cutoff
  if (summary.openBugs >= 5) {
    recs.push(`Schedule a bug triage session to review ${summary.openBugs} open bugs`);
  }

  return recs; // empty when nothing qualifies
}

private generateExcel(report: BugIntelReport, outputPath: string): void {
  const XLSX = require('xlsx'); // lazy require — dry-run never loads the writer
  const wb = XLSX.utils.book_new();
  const s = report.summary;

  // Array-of-arrays: each row is an array; [] is a blank spacer row
  const summaryRows: any[][] = [
    ['Bug Intelligence Summary'],
    [],
    ['Metric', 'Value'],
    ['Total Bugs', s.totalBugs],
    ['Open Bugs', s.openBugs],
    ['Fixed Bugs', s.fixedBugs],
    ['Fix Rate', `${Math.round(s.fixRate * 100)}%`], // 0..1 float -> "81%"
    ['Avg Days to Fix', s.avgDaysToFix ?? 'N/A'],    // ?? keeps a real 0; only null/undefined -> N/A
  ];
  const summaryWs = XLSX.utils.aoa_to_sheet(summaryRows);
  XLSX.utils.book_append_sheet(wb, summaryWs, 'Summary'); // sheet tab name

  // ... plus 'All Bugs', 'Per-Story', and 'Severity x State Pivot' sheets

  XLSX.writeFile(wb, outputPath); // flush the whole workbook to disk in one call
}
